questiontext.text:
Your goal is to find the equation of the line of reflection between the fixed green and pink arrows.
        <center>
[[jsxgraph input-ref-ans2="ref_P" input-ref-ans3="ref_Q" height="500px" width="500px"]]

    JXG.Options.text.useMathJax=true;
    var board = JXG.JSXGraph.initBoard(divid, {
      boundingBox:[-7,7,7,-7],
      showCopyright:false,
      showNavigation:false,
      keepaspectratio:true,
      axis:true,
      defaultAxes: {
            x: { ticks: { insertTicks: false, ticksDistance: 1, minorTicks: 0, drawLabels: true } },
            y: { ticks: { insertTicks: false, ticksDistance: 1, minorTicks: 0, drawLabels: true } }
        }
    });

    var initCenCoords = {#initCen#};
    var initTipCoords = {#initTip#};
    var refCenCoords = {#refCen#};

    // Fixed initial shape (PINK)

    var vertexStyle = {
      visible:false,
      fixed:true
    };

    var initFixedCen = board.create("point", initCenCoords, vertexStyle);
    var initFixedTip = board.create("point", initTipCoords, vertexStyle);

    var constLine1 = board.create("line", [initFixedCen, initFixedTip], {visible:false});
    var constLine2 = board.create("perpendicular", [
      [5*initFixedCen.X()/2-3*initFixedTip.X()/2, 5*initFixedCen.Y()/2-3*initFixedTip.Y()/2],
      constLine1
    ], {visible:false});
    var constLine3 = board.create("parallel", [
      [initFixedCen.X()+(initFixedTip.Y()-initFixedCen.Y())/2, initFixedCen.Y()+(initFixedTip.X()-initFixedCen.X())/2],
      constLine1
    ], {visible:false});
    var constLine4 = board.create("parallel", [
      [initFixedCen.X()-(initFixedTip.Y()-initFixedCen.Y())/2, initFixedCen.Y()-(initFixedTip.X()-initFixedCen.X())/2],
      constLine1
    ], {visible:false});

    var initFixedPointList = [
      initFixedCen,
      initFixedTip,
      board.create("point", [
        initFixedCen.X()+(initFixedTip.Y()-initFixedCen.Y()),
        initFixedCen.Y()+(initFixedTip.X()-initFixedCen.X())
      ], vertexStyle),
      board.create("point", [
        initFixedCen.X()+(initFixedTip.Y()-initFixedCen.Y())/2,
        initFixedCen.Y()+(initFixedTip.X()-initFixedCen.X())/2
      ], vertexStyle),
      board.create("intersection", [constLine2,constLine3], vertexStyle),
      board.create("intersection", [constLine2,constLine4], vertexStyle),
      board.create("point", [
        initFixedCen.X()-(initFixedTip.Y()-initFixedCen.Y())/2,
        initFixedCen.Y()-(initFixedTip.X()-initFixedCen.X())/2
      ], vertexStyle),
      board.create("point", [
        initFixedCen.X()-(initFixedTip.Y()-initFixedCen.Y()),
        initFixedCen.Y()-(initFixedTip.X()-initFixedCen.X())
      ], vertexStyle),
    ];

    board.create("polygon", initFixedPointList.slice(1), {
      fixed:true,
      highlight:false,
      fillColor:"pink",
      fillOpacity:0.7,
      borders:{
        visible:false
      }
    });

    // Fixed reflected shape (GREEN)

    var fixedCen = board.create("point", refCenCoords, vertexStyle);

    var cenJoin = board.create("line", [initCenCoords,refCenCoords], {visible:false});
    var cenMid = board.create("midpoint", [initCenCoords,refCenCoords], {visible:false});
    var refLine = board.create("perpendicular", [cenMid, cenJoin], {visible:false});

    var fixedTip = board.create("reflection", [initFixedTip,refLine], vertexStyle);

    var constLine1 = board.create("line", [fixedCen, fixedTip], {visible:false});
    var constLine2 = board.create("perpendicular", [
      [5*fixedCen.X()/2-3*fixedTip.X()/2, 5*fixedCen.Y()/2-3*fixedTip.Y()/2],
      constLine1
    ], {visible:false});
    var constLine3 = board.create("parallel", [
      [fixedCen.X()+(fixedTip.Y()-fixedCen.Y())/2, fixedCen.Y()+(fixedTip.X()-fixedCen.X())/2],
      constLine1
    ], {visible:false});
    var constLine4 = board.create("parallel", [
      [fixedCen.X()-(fixedTip.Y()-fixedCen.Y())/2, fixedCen.Y()-(fixedTip.X()-fixedCen.X())/2],
      constLine1
    ], {visible:false});

    var fixedPointList = [
      fixedCen,
      fixedTip,
      board.create("point", [
        fixedCen.X()+(fixedTip.Y()-fixedCen.Y()),
        fixedCen.Y()+(fixedTip.X()-fixedCen.X())
      ], vertexStyle),
      board.create("point", [
        fixedCen.X()+(fixedTip.Y()-fixedCen.Y())/2,
        fixedCen.Y()+(fixedTip.X()-fixedCen.X())/2
      ], vertexStyle),
      board.create("intersection", [constLine2,constLine3], vertexStyle),
      board.create("intersection", [constLine2,constLine4], vertexStyle),
      board.create("point", [
        fixedCen.X()-(fixedTip.Y()-fixedCen.Y())/2,
        fixedCen.Y()-(fixedTip.X()-fixedCen.X())/2
      ], vertexStyle),
      board.create("point", [
        fixedCen.X()-(fixedTip.Y()-fixedCen.Y()),
        fixedCen.Y()-(fixedTip.X()-fixedCen.X())
      ], vertexStyle),
    ];

    board.create("polygon", fixedPointList.slice(1), {
      fixed:true,
      highlight:false,
      fillColor:"ForestGreen",
      fillOpacity:0.7,
      borders:{
        visible:false
      }
    });

    // ---- Movable line of reflection (bound to ans2/ans3; marked) ----
    // Two draggable purple points define the line. Its equation is never shown.
    var dragP = board.create("point", [-5, 1], {
      name:"", size:4, strokeColor:"purple", fillColor:"purple",
      snapToGrid:true, snapSizeX:1, snapSizeY:1, label:{visible:false}
    });
    var dragQ = board.create("point", [-2, 1], {
      name:"", size:4, strokeColor:"purple", fillColor:"purple",
      snapToGrid:true, snapSizeX:1, snapSizeY:1, label:{visible:false}
    });
    var userLine = board.create("line", [dragP, dragQ], {
      strokeColor:"purple", strokeWidth:2, dash:2, highlight:false
    });

    // Live reflection of the PINK shape across the movable line (yellow).
    var userReflPts = [];
    for (var i=1; i<initFixedPointList.length; i++){
      userReflPts.push(board.create("reflection", [initFixedPointList[i], userLine], {visible:false, fixed:true}));
    }
    board.create("polygon", userReflPts, {
      fixed:true,
      highlight:false,
      fillColor:"gold",
      fillOpacity:0.55,
      borders:{ visible:true, strokeColor:"darkorange", strokeWidth:2, dash:2 }
    });

    // Bind the two purple points to the STACK inputs so the line is marked.
    stack_jxg.bind_point(ref_P, dragP);
    stack_jxg.bind_point(ref_Q, dragQ);

    board.unsuspendUpdate();

[[/jsxgraph]]
</center>

<p>The yellow arrow is the reflection of the pink arrow on the test purple line. Move the purple line (by dragging its points or clicking and dragging the line itself) so that the yellow arrow lands exactly on top of the green arrow.</p>
<div align="left">[[feedback:prt2]]</div>

<p><br>Find the equation of the line of reflection between the fixed green and pink arrows.</p>
<div align="left">[[input:ans1]] [[validation:ans1]]</div>
<div align="left">[[feedback:prt1]]</div>
<div align="left">[[feedback:prt3]]</div>

<div style="display:none">[[input:ans2]] [[validation:ans2]] [[input:ans3]] [[validation:ans3]]</div>

questionvariables.text:
/* Initial position */
initCen:[rand([1,-1])*rand([2,3,4]), rand([1,-1])*rand([2,3,4])];
initTipOffset:random_permutation([0,rand([1,-1])*2]);
initTip:[first(initCen)+first(initTipOffset), second(initCen)+second(initTipOffset)];

/* Reflected shape */
cenTrans:rand_with_prohib(4, min(abs(first(initCen)),abs(second(initCen)))+4, [abs(first(initCen))+abs(second(initCen))]);
refCen:[first(initCen)+(if first(initCen)>=0 then -1 else 1)*cenTrans, second(initCen)+(if second(initCen)>=0 then -1 else 1)*cenTrans];

/* Finding line of reflection */
cenMid: [(first(initCen)+first(refCen))/2,(second(initCen)+second(refCen))/2];
tans1: if sign(first(initCen))=sign(second(initCen)) then y=first(cenMid)+second(cenMid)-x else y=x+second(cenMid)-first(cenMid);

/* Gradient/intercept of the mirror, and two lattice points on it (model answer for the draggable line) */
grad1: if sign(first(initCen))=sign(second(initCen)) then -1 else 1;
icpt1: if sign(first(initCen))=sign(second(initCen)) then first(cenMid)+second(cenMid) else second(cenMid)-first(cenMid);
lpt1: [0, icpt1];
lpt2: [2, 2*grad1+icpt1];

feedbackvariables.text:
/* Node 0: full-mark check via AlgEquiv */
/* Node 2: correct gradient (coefficient of x relative to y) */
node3_test: if abs((coeff(lhs(ans1)-rhs(ans1),x)/coeff(lhs(ans1)-rhs(ans1),y))-(coeff(lhs(tans1)-rhs(tans1),x)/coeff(lhs(tans1)-rhs(tans1),y)))<=0.0001 then 1 else 0;

/* Node 3: correct y-intercept (relative to y) */
node4_test: if abs((coeff(lhs(ans1)-rhs(ans1),x,0)/coeff(lhs(ans1)-rhs(ans1),y))-(coeff(lhs(tans1)-rhs(tans1),x,0)/coeff(lhs(tans1)-rhs(tans1),y)))<=0.0001 then 1 else 0;

/* Does the student's line (through the two purple points) coincide with the mirror? */
mline: lhs(tans1)-rhs(tans1);
resP: float(ev(mline, x=first(ans2), y=second(ans2)));
resQ: float(ev(mline, x=first(ans3), y=second(ans3)));
lineOK: if is(abs(resP)<0.01) and is(abs(resQ)<0.01) and is(ans2#ans3) then 1 else 0;

/* Recompute whether the drawn line is correct (feedback vars are per-PRT). */
mline: lhs(tans1)-rhs(tans1);
resP: float(ev(mline, x=first(ans2), y=second(ans2)));
resQ: float(ev(mline, x=first(ans3), y=second(ans3)));
lineOK: if is(abs(resP)<0.01) and is(abs(resQ)<0.01) and is(ans2#ans3) then 1 else 0;
